export const RTL_LANGUAGES = new Set(["ur", "sd", "ks"]);

export function isRTL(langCode) {
  if (!langCode) return false;
  return RTL_LANGUAGES.has(String(langCode).toLowerCase().trim());
}

export function getLanguageInfo(langCode) {
  const code = String(langCode || "en").toLowerCase().trim();
  return SUPPORTED_LANGUAGES.find((l) => l.code === code) || SUPPORTED_LANGUAGES[0];
}

